def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); strata = sorted(set(feats.stratum))
    S = np.array([[1.0 if s == t else 0.0 for t in strata[1:]] for s in feats.stratum]).reshape(n, -1)
    base = np.hstack([np.ones((n, 1)), S])
    def fit(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu))), mu
    def M(cols, extra=None):
        Z = [base] + [X[:, [c]] for c in cols]
        if extra is not None: Z.append(extra[:, None])
        return np.hstack(Z)
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    sel = []; ll0, _ = fit(M(sel))
    while len(sel) < MAX_DRIVERS:
        alpha = (0.05 if not sel else 0.01) / p
        cand = [j for j in range(p) if j not in sel and all(abs(R[j, k]) < 0.6 for k in sel)]
        if not cand: break
        lls = {j: fit(M(sel + [j]))[0] for j in cand}
        j = max(lls, key=lls.get)
        if stats.chi2.sf(2 * (lls[j] - ll0), 1) > alpha: break
        clus = [k for k in cand if abs(R[j, k]) >= 0.6 or k == j]
        ok = [k for k in clus if lls[k] >= lls[j] - 2]
        j = max(ok, key=lambda k: sum(R[k, m] ** 2 for m in clus))
        sel.append(j); ll0 = lls[j]
    changed = True
    while changed and sel:
        changed = False; full, _ = fit(M(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - fit(M(rest))[0]), 1) > 0.01 / p:
                sel = rest; changed = True; break
    _, mu = fit(M(sel)); r = y - mu; w = mu * (1 - mu)
    pairs = [(a, b) for a in range(p) for b in range(a, p) if a == b or abs(R[a, b]) < 0.6]
    sc = []
    for a, b in pairs:
        v = X[:, a] * X[:, b]; v = v - v.mean()
        sc.append((np.dot(v, r) ** 2 / (np.dot(w, v * v) + 1e-9), a, b))
    sc.sort(reverse=True); prods = []; npair = p * (p + 1) / 2
    for _, a, b in sc[:15]:
        mains = sorted(set(sel) | {a, b}); l1, _ = fit(M(mains))
        l2, _ = fit(M(mains, X[:, a] * X[:, b]))
        if stats.chi2.sf(2 * (l2 - l1), 1) < 0.01 / npair: prods.append((a, b, l2 - l1))
    prods.sort(key=lambda t: -t[2]); chosen = []
    for a, b, _ in prods:
        if len(chosen) < 2 and not any({a, b} & {c, d} for c, d in chosen): chosen.append((a, b))
    drivers = [ids[j] for j in sel]
    for a, b in chosen:
        for j in (a, b):
            if ids[j] not in drivers: drivers.append(ids[j])
    cols = sorted(set(sel) | {j for ab in chosen for j in ab})
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in chosen), loadings={})

